<?php require_once __DIR__ . '/../../includes/layout.php'; require_role(['Student','Admin']); render_header('My Schedule'); ?><div class="page-title"><div><h1>My Schedule</h1><p>Weekly class schedule.</p></div></div><div class="panel"><table class="table"><thead><tr><th>Day</th><th>Time</th><th>Subject</th><th>Room</th></tr></thead><tbody><?php foreach(rows('SELECT sc.*,sub.code,sub.title FROM schedules sc JOIN subjects sub ON sub.id=sc.subject_id WHERE sc.section_id IN (SELECT s.section_id FROM students s WHERE '.student_scope_sql().') ORDER BY CASE sc.day_of_week WHEN \'Monday\' THEN 1 WHEN \'Tuesday\' THEN 2 WHEN \'Wednesday\' THEN 3 WHEN \'Thursday\' THEN 4 WHEN \'Friday\' THEN 5 WHEN \'Saturday\' THEN 6 ELSE 7 END,sc.start_time') as $s): ?><tr><td><?= e($s['day_of_week']) ?></td><td><?= e($s['start_time'].' - '.$s['end_time']) ?></td><td><?= e($s['code'].' - '.$s['title']) ?></td><td><?= e($s['room']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php render_footer(); ?>
